public class Animal {
  protected string $species = "Mammal"
  public func getSpecies(): string {
    return $this->species
  }
}
public class Dog extends Animal {
  public func describe(): string {
    return "Dog:" . $this->species
  }
}
public func main(): string {
  Dog $d = new Dog()
  return $d->describe()
}
